<?php
require __DIR__.'/_init.php';
$action=$_GET['action']??'';
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$mode=$_POST['mode']??'save';
 if($mode==='delete'){$id=(int)($_POST['id']??0);$s=$pdo->prepare('DELETE FROM products WHERE id=?');$s->execute([$id]);flash('success','محصول حذف شد.');header('Location: '.site_url('admin/products.php'));exit;}
 $id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$category=trim((string)($_POST['category']??'عمومی'));$description=trim((string)($_POST['description']??''));$price=max(0,(int)($_POST['price']??0));$active=isset($_POST['is_active'])?1:0;$featured=isset($_POST['is_featured'])?1:0;$image=null;
 if($name===''||$price<1){flash('error','نام محصول و قیمت معتبر الزامی است.');header('Location: '.site_url('admin/products.php?action='.($id?'edit&id='.$id:'new')));exit;}
 if(isset($_FILES['image'])&&$_FILES['image']['error']!==UPLOAD_ERR_NO_FILE){
  $f=$_FILES['image'];$max=(int)($config['upload_max_bytes']??5242880);
  if($f['error']!==UPLOAD_ERR_OK||$f['size']>$max){flash('error','حجم تصویر بیش از حد مجاز است یا بارگذاری ناموفق بود.');header('Location: '.site_url('admin/products.php?action='.($id?'edit&id='.$id:'new')));exit;}
  $mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];
  if(!isset($allowed[$mime])){flash('error','فقط تصویر JPG، PNG یا WEBP مجاز است.');header('Location: '.site_url('admin/products.php?action='.($id?'edit&id='.$id:'new')));exit;}
  $image=bin2hex(random_bytes(12)).'.'.$allowed[$mime];$dir=__DIR__.'/../storage/uploads';if(!is_dir($dir))mkdir($dir,0755,true);
  if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$image)){$image=null;flash('error','ذخیره تصویر ناموفق بود.');header('Location: '.site_url('admin/products.php?action='.($id?'edit&id='.$id:'new')));exit;}
 }
 if($id){if($image){$s=$pdo->prepare('UPDATE products SET name=?,category=?,description=?,price=?,image=?,is_active=?,is_featured=? WHERE id=?');$s->execute([$name,$category,$description,$price,$image,$active,$featured,$id]);}else{$s=$pdo->prepare('UPDATE products SET name=?,category=?,description=?,price=?,is_active=?,is_featured=? WHERE id=?');$s->execute([$name,$category,$description,$price,$active,$featured,$id]);}flash('success','محصول به‌روزرسانی شد.');}
 else{$s=$pdo->prepare('INSERT INTO products(name,category,description,price,image,is_active,is_featured,created_at) VALUES(?,?,?,?,?,?,?,NOW())');$s->execute([$name,$category,$description,$price,$image,$active,$featured]);flash('success','محصول اضافه شد.');}
 header('Location: '.site_url('admin/products.php'));exit;
}
$editing=null;if($action==='edit'){$s=$pdo->prepare('SELECT * FROM products WHERE id=?');$s->execute([(int)($_GET['id']??0)]);$editing=$s->fetch();if(!$editing){flash('error','محصول پیدا نشد.');header('Location: '.site_url('admin/products.php'));exit;}}
$list=$pdo->query('SELECT * FROM products ORDER BY created_at DESC')->fetchAll();
render_header('مدیریت محصولات');
?><main class="container"><div class="page-title"><h1>مدیریت محصولات</h1><p>افزودن، ویرایش، نمایش و حذف محصولات.</p></div><div class="admin-layout"><aside class="admin-nav"><a href="<?=e(site_url('admin/index.php'))?>">داشبورد</a><a href="<?=e(site_url('admin/products.php'))?>">محصولات</a><a href="<?=e(site_url('admin/orders.php'))?>">سفارش‌ها</a><a href="<?=e(site_url('admin/logout.php'))?>">خروج</a></aside><section class="admin-content">
