<div class="form-card" style="margin:0 0 25px"><h2><?=$editing?'ویرایش محصول':'محصول جدید'?></h2><form method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="mode" value="save"><input type="hidden" name="id" value="<?=e($p['id'])?>"><div class="form-grid"><div class="form-group"><label>نام محصول *</label><input name="name" required value="<?=e($p['name'])?>"></div><div class="form-group"><label>دسته‌بندی</label><input name="category" value="<?=e($p['category'])?>" required></div><div class="form-group"><label>قیمت پایه (تومان) *</label><input type="number" name="price" min="1" required value="<?=e($p['price'])?>"></div><div class="form-group"><label>تصویر (JPG/PNG/WEBP)</label><input type="file" name="image" accept="image/jpeg,image/png,image/webp"><?php if($p['image']): ?><img src="<?=e(product_image($p['image']))?>" alt="" style="width:100px;margin-top:8px"><?php endif; ?></div><div class="form-group full"><label>توضیحات</label><textarea name="description" rows="4"><?=e($p['description'])?></textarea></div><div class="form-group"><label><input type="checkbox" name="is_active" <?=$p['is_active']?'checked':''?>> نمایش در فروشگاه</label></div><div class="form-group"><label><input type="checkbox" name="is_featured" <?=$p['is_featured']?'checked':''?>> محصول منتخب</label></div></div><p><button class="btn">ذخیره محصول</button> <a class="btn secondary" href="<?=e(site_url('admin/products.php'))?>">انصراف</a></p></form></div>
<?php else: ?><p><a class="btn" href="<?=e(site_url('admin/products.php?action=new'))?>">+ افزودن محصول</a></p><div class="table-wrap"><table class="table"><thead><tr><th>محصول</th><th>دسته</th><th>قیمت</th><th>وضعیت</th><th>عملیات</th></tr></thead><tbody><?php foreach($list as $p): ?><tr><td><?=e($p['name'])?></td><td><?=e($p['category'])?></td><td><?=money($p['price'])?></td><td><?=$p['is_active']?'فعال':'مخفی'?></td><td><a class="small-btn" href="<?=e(site_url('admin/products.php?action=edit&id='.$p['id']))?>">ویرایش</a> <form method="post" class="inline-form" style="display:inline-flex" onsubmit="return confirm('محصول حذف شود؟')"><?=csrf_field()?><input type="hidden" name="mode" value="delete"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="small-btn danger">حذف</button></form></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
